<div class="table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Stop</th><th>Cost</th><th>Action</th></tr></thead><tbody><?php foreach ($activities as $activity): ?><tr><td><?php echo h($activity['name']); ?></td><td><?php echo h((string)$activity['activity_type']); ?></td><td><?php echo h($activity['city']); ?></td><td>EUR <?php echo number_format((float)$activity['estimated_cost'], 2); ?></td><td><form method="post"><input type="hidden" name="action" value="delete_activity"><input type="hidden" name="id" value="<?php echo $activity['id']; ?>"><button class="danger" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div>
